const out = $input.all().map(item => {
  const inv = item.json.abstract_inverted_index || {};
  const words = [];
  for (const [word, positions] of Object.entries(inv)) {
    for (const p of positions) {
      words[p] = word;
    }
  }
  const rest = { ...item.json };
  delete rest.abstract_inverted_index;
  return { json: { ...rest, abstract: words.join(' ') } };
});
return out;

